dynamic order = new ExpandoObject();
order.RoutingSlip = "RS-17";              // member added at run time
IDictionary<string, object?> bag = order; // same object, dictionary view
bag["Colour"] = "red";
bag.Remove("RoutingSlip");
foreach (var pair in bag) Console.WriteLine(pair.Key);   // discoverability

class Bag : DynamicObject {               // own name -> value semantics
    readonly Dictionary<string, object?> _map = new();
    public override IEnumerable<string> GetDynamicMemberNames() => _map.Keys;
}
